const store = {
  async get(k) {
    if (typeof window !== "undefined" && window.storage) {
      try { return await window.storage.get(k, true); } catch { return null; }
    }
    return k in mem ? { key: k, value: mem[k] } : null;
  },
  async set(k, v) {
    if (typeof window !== "undefined" && window.storage) {
      try { return await window.storage.set(k, v, true); } catch { return null; }
    }
    mem[k] = v; return { key: k, value: v };
  },
};

function usePersistent(key, initial) {
  const [value, setValue] = useState(initial);
  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    let alive = true;
    (async () => {
      const r = await store.get(key);
      if (alive && r && r.value != null) {
        try { setValue(JSON.parse(r.value)); } catch {}
      }
      if (alive) setLoaded(true);
    })();
    return () => { alive = false; };
  }, [key]);
  useEffect(() => {
    if (!loaded) return;
    store.set(key, JSON.stringify(value));
  }, [key, value, loaded]);
  return [value, setValue, loaded];
}

