const CAT_LABELS = {
  "1": "Crédito ilimitado",
  "2": "Crédito $5.000.000",
  "3": "Crédito $3.000.000",
  "4": "Crédito $1.000.000",
  "5": "Contado",
};
const CAT_LIMITE = { "1": Infinity, "2": 5000000, "3": 3000000, "4": 1000000, "5": 0 };
function calcularEstadoCuenta(clienteId, categoria, pedidos, pagos) {
  const limite = CAT_LIMITE[String(categoria)] ?? 0;
  const totalCredito = (pedidos || []).filter((p) => p.clienteId === clienteId && p.metodoPago === "Crédito (factura)" && p.estado !== "Cancelado")
    .reduce((s, p) => s + Number(p.total || 0), 0);
  const totalPagado = (pagos || []).filter((pg) => pg.clienteId === clienteId && pg.estado === "Confirmado")
    .reduce((s, pg) => s + Number(pg.monto || 0), 0);
  const deuda = Math.max(0, totalCredito - totalPagado);
  const disponible = limite === Infinity ? Infinity : limite - deuda;
  return { limite, totalCredito, totalPagado, deuda, disponible };
}
/* Cartola de movimientos (estilo tarjeta de crédito): compras a crédito suman, abonos confirmados restan, con saldo corriendo */
function fechaVencimientoFactura(fechaBase, metodoPago) {
  if (metodoPago !== "Crédito (factura)" && metodoPago !== "Transferencia bancaria") return "";
  const d = new Date(fechaBase + "T00:00:00");
  d.setDate(d.getDate() + 30);
  return d.toISOString().slice(0, 10);
}
function calcularMovimientos(clienteId, pedidos, pagos) {
  const compras = (pedidos || [])
    .filter((p) => p.clienteId === clienteId && p.metodoPago === "Crédito (factura)" && p.estado !== "Cancelado")
    .map((p) => ({ fecha: p.fecha, tipo: "Compra", descripcion: "Pedido " + p.numero, monto: Number(p.total || 0) }));
  const abonos = (pagos || [])
    .filter((pg) => pg.clienteId === clienteId && pg.estado === "Confirmado")
    .map((pg) => ({ fecha: pg.fecha, tipo: "Abono", descripcion: pg.metodo + (pg.pedidoId ? " · pedido" : ""), monto: -Number(pg.monto || 0) }));
  const movs = [...compras, ...abonos].sort((a, b) => a.fecha.localeCompare(b.fecha));
  let saldo = 0;
  return movs.map((m) => { saldo += m.monto; return { ...m, saldo }; }).reverse(); // más reciente primero
}
const ETAPA_PEDIDO_CLIENTE = ["Confirmación", "Preparación", "Despacho", "Entregado"];
function etapaPedidoCliente(estado) {
  if (estado === "Cancelado") return -1;
  if (estado === "Pendiente" || estado === "Confirmado") return 0;
  if (estado === "En preparación") return 1;
  if (estado === "Despachado") return 2;
  if (estado === "Entregado") return 3;
  return 0;
}

