/* ---------- Utilidades ---------- */
const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
const today = () => new Date().toISOString().slice(0, 10);
const fmtCLP = (n) => "$" + (Number(n) || 0).toLocaleString("es-CL");
const daysBetween = (a, b) => Math.round((new Date(b) - new Date(a)) / 86400000);

// Acciones pendientes del vendedor (o de toda la empresa si es admin): usado para el indicador del menú y "Mi Día".
function accionesPendientes(db) {
  const { me, clientes, visitas } = db;
  const mine = (arr, key = "vendedorId") => me.role === "admin" ? arr : arr.filter((x) => x[key] === me.id);
  const cl = mine(clientes).filter((c) => c.estado === "Cliente");
  const vs = mine(visitas);
  const visHoy = vs.filter((v) => v.estado === "Programada" && v.fecha === today());
  const realizadas = vs.filter((v) => v.estado !== "Programada");
  const conRiesgo = cl.map((c) => {
    const ult = realizadas.filter((v) => v.clienteId === c.id).map((v) => v.fecha).sort().pop();
    return { c, ult, dias: ult ? daysBetween(ult, today()) : null };
  }).filter((r) => r.dias != null && r.dias >= 15).sort((a, b) => b.dias - a.dias);
  const criticos = conRiesgo.filter((r) => r.dias >= 61);
  const alertas30 = conRiesgo.filter((r) => r.dias >= 30);
  return { visHoy, revisitas: conRiesgo, criticos, alertas30, total: visHoy.length + conRiesgo.length };
}

function mapsDir(dest) {
  return "https://www.google.com/maps/dir/?api=1&destination=" + encodeURIComponent(dest);
}
/* Normaliza cualquier formato de número chileno a dígitos limpios con código de país (56...) */
/* Formatea un RUT chileno al modelo XX.XXX.XXX-X mientras se escribe */
function formatearRutCL(valor) {
  let v = String(valor || "").replace(/[^0-9kK]/g, "").toUpperCase();
  if (!v) return "";
  const dv = v.slice(-1);
  let cuerpo = v.slice(0, -1);
  if (!cuerpo) return dv;
  cuerpo = cuerpo.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return cuerpo + "-" + dv;
}
function normalizarTelefonoCL(tel) {
  let d = String(tel || "").replace(/\D/g, "");
  if (!d) return "";
  if (d.startsWith("56")) d = d.slice(2);
  d = d.replace(/^0+/, ""); // quita ceros sueltos al inicio (típico error al tipear)
  if (!d) return "";
  return "56" + d;
}
/* Formatea para mostrar: +56 9 1234 5678 (móvil) o +56 2 2345 6789 (fijo) */
function formatearTelefonoCL(tel) {
  const d = normalizarTelefonoCL(tel);
  if (!d) return "";
  const nac = d.slice(2); // parte nacional, sin 56
  if (nac.length === 9 && nac.startsWith("9")) {
    return "+56 9 " + nac.slice(1, 5) + " " + nac.slice(5);
  }
  if (nac.length === 8) {
    return "+56 " + nac.slice(0, 1) + " " + nac.slice(1, 5) + " " + nac.slice(5);
  }
  return "+56 " + nac;
}
function whatsappUrl(tel, text) {
  const num = normalizarTelefonoCL(tel);
  if (!num || num.length < 10) return null;
  return "https://wa.me/" + num + (text ? "?text=" + encodeURIComponent(text) : "");
}
