function QtyInput({ value, onCommit }) {
  const [texto, setTexto] = useState(String(value));
  useEffect(() => { setTexto(String(value)); }, [value]);
  const commit = () => {
    const n = Math.max(0, Math.floor(Number(texto) || 0));
    onCommit(n);
    setTexto(String(n));
  };
  return (
    <input type="number" className="qty-input" min="0" value={texto}
      onChange={(e) => setTexto(e.target.value)}
      onFocus={(e) => e.target.select()}
      onBlur={commit}
      onKeyDown={(e) => { if (e.key === "Enter") { e.target.blur(); } }} />
  );
}
function WaBtn({ tel, small }) {
  const url = whatsappUrl(tel);
  if (!url) return null;
  return (
    <a href={url} target="_blank" rel="noreferrer" className={"sel-go wa" + (small ? " sm" : "")} title={"WhatsApp " + tel}>{LOGO_WA}</a>
  );
}
/* ---------- Dictado por voz (notas y observaciones) ---------- */
function MicBtn({ value, onChange, small }) {
  const [listening, setListening] = useState(false);
  const [err, setErr] = useState("");
  const recRef = useRef(null);
  const SR = typeof window !== "undefined" && (window.SpeechRecognition || window.webkitSpeechRecognition);
  if (!SR) return null; // no soportado en este navegador (ej. algunos Safari/iOS)

  const toggle = () => {
    if (listening) { recRef.current?.stop(); return; }
    setErr("");
    const rec = new SR();
    rec.lang = "es-CL";
    rec.continuous = false;
    rec.interimResults = false;
    rec.onstart = () => setListening(true);
    rec.onerror = (e) => { setErr(e.error === "not-allowed" ? "Permiso de micrófono denegado" : "No se pudo escuchar"); setListening(false); };
    rec.onend = () => setListening(false);
    rec.onresult = (e) => {
      const texto = Array.from(e.results).map((r) => r[0].transcript).join(" ").trim();
      if (texto) onChange(((value || "").trim() ? value.trim() + " " : "") + texto);
    };
    recRef.current = rec;
    try { rec.start(); } catch { setErr("No se pudo iniciar el micrófono"); }
  };

  return (
    <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
      <button type="button" className={"btn" + (small ? " btn-sm" : "")}
        onClick={toggle} title={listening ? "Detener dictado" : "Dictar por voz"}
        style={listening ? { borderColor: "var(--red)", color: "var(--red)" } : undefined}>
        {listening ? "⏹ Escuchando…" : "🎤 Dictar"}
      </button>
      {err && <span className="muted small" style={{ color: "var(--red)" }}>{err}</span>}
    </span>
  );
}
function mapsMulti(stops) {
  if (!stops.length) return "https://www.google.com/maps";
  const dest = encodeURIComponent(stops[stops.length - 1]);
  const wp = stops.slice(0, -1).map(encodeURIComponent).join("|");
  let u = "https://www.google.com/maps/dir/?api=1&destination=" + dest + "&travelmode=driving";
  if (wp) u += "&waypoints=" + wp;
  return u;
}
function wazeUrl(addr, coord) {
  if (coord && coord.length === 2) return "https://waze.com/ul?ll=" + coord[0] + "," + coord[1] + "&navigate=yes";
  return "https://waze.com/ul?q=" + encodeURIComponent(addr) + "&navigate=yes";
}
function mapsEmbed(addrs) {
  const a = addrs.filter(Boolean);
  if (a.length === 0) return null;
  if (a.length === 1) return "https://maps.google.com/maps?q=" + encodeURIComponent(a[0]) + "&z=12&output=embed";
  const saddr = encodeURIComponent(a[0]);
  const daddr = a.slice(1).map(encodeURIComponent).join("+to:");
  return "https://maps.google.com/maps?saddr=" + saddr + "&daddr=" + daddr + "&output=embed";
}

